'use client'

import * as DropdownMenu from '@radix-ui/react-dropdown-menu'
import { Palette as PaletteIcon } from 'lucide-react'
import { useFrontendPreferences } from './context.js'
import { shellMessages } from './messages.js'
import { isMode, isPalette } from './preferences.js'
import { MODES, PALETTES } from './types.js'
import { Button } from './ui/button.js'
import { menuClass } from './ui/classes.js'
import { cn } from './ui/cn.js'
import { MenuChoice } from './ui/menu-choice.js'

export function AppearanceMenu(): React.JSX.Element {
  const state = useFrontendPreferences()
  const messages = shellMessages(state.preferences.locale)
  return (
    <DropdownMenu.Root>
      <DropdownMenu.Trigger asChild>
        <Button className={cn('gap-1.5 px-2')} variant="ghost" aria-label={messages.appearance}>
          <PaletteIcon aria-hidden="true" size={16} />
          <span className={cn('ztd-wide-label hidden sm:inline')}>{messages.appearance}</span>
        </Button>
      </DropdownMenu.Trigger>
      <DropdownMenu.Portal container={state.portalContainer}>
        <DropdownMenu.Content className={cn(`${menuClass} w-55`)} sideOffset={8} align="end">
          <DropdownMenu.Label
            className={cn('ztd-menu-label px-2 py-1.5 text-help text-muted-foreground')}
          >
            {messages.mode}
          </DropdownMenu.Label>
          <DropdownMenu.RadioGroup
            value={state.preferences.mode}
            onValueChange={(mode) => {
              if (isMode(mode)) {
                state.setMode(mode)
              }
            }}
          >
            {MODES.map(mode => <MenuChoice key={mode} value={mode}>{messages.modes[mode]}</MenuChoice>)}
          </DropdownMenu.RadioGroup>
          <DropdownMenu.Separator className={cn('ztd-separator mx-1.5 my-1.5 h-px bg-border')} />
          <DropdownMenu.Label
            className={cn('ztd-menu-label px-2 py-1.5 text-help text-muted-foreground')}
          >
            {messages.palette}
          </DropdownMenu.Label>
          <DropdownMenu.RadioGroup
            value={state.preferences.palette}
            onValueChange={(palette) => {
              if (isPalette(palette)) {
                state.setPalette(palette)
              }
            }}
          >
            {PALETTES.map(palette => (
              <MenuChoice key={palette} value={palette}>
                <span
                  className={cn('ztd-swatch size-3 rounded-full border border-border bg-foreground')}
                  data-swatch={palette}
                  style={{ backgroundColor: `var(--ztd-swatch-${palette})` }}
                  aria-hidden="true"
                />
                {messages.palettes[palette]}
              </MenuChoice>
            ))}
          </DropdownMenu.RadioGroup>
        </DropdownMenu.Content>
      </DropdownMenu.Portal>
    </DropdownMenu.Root>
  )
}

import type { FrontendPreferences, PreferenceCookieResult, PreferencePolicy } from './types.js'
import { preferenceCookie, readPreferenceCookie } from './cookies.js'
import { serializePreferences } from './preferences.js'

function browserCookieHeader(): string | null {
  try {
    return document.cookie
  }
  catch {
    return null
  }
}
export function readBrowserPreferences(policy: PreferencePolicy):
  PreferenceCookieResult | { status: 'unavailable', preferences: null } {
  const header = browserCookieHeader()
  return header === null
    ? { status: 'unavailable', preferences: null }
    : readPreferenceCookie(header, policy)
}
export function persistBrowserPreferences(preferences: FrontendPreferences, policy: PreferencePolicy): boolean {
  try {
    document.cookie = preferenceCookie(preferences, policy)
    const read = readBrowserPreferences(policy)
    if (read.preferences === null || serializePreferences(read.preferences) !== serializePreferences(preferences)) {
      return false
    }
    try {
      if (policy.mirrorKey !== undefined) {
        localStorage.setItem(policy.mirrorKey, serializePreferences(preferences))
      }
    }
    catch {
      // Cookie persistence still works when the optional same-origin notification mirror is unavailable.
    }
    return true
  }
  catch {
    return false
  }
}

'use client'

import type { PreferenceSnapshot, PreferenceStore } from './store-types.js'
import { createContext, use } from 'react'

export type PreferenceContextValue = {
  setMode: PreferenceStore['setMode']
  setPalette: PreferenceStore['setPalette']
  setLocale: PreferenceStore['setLocale']
  portalContainer: HTMLElement | null
  styleNonce: string | undefined
} & PreferenceSnapshot
export const PreferenceContext = createContext<PreferenceContextValue | null>(null)
export function useFrontendPreferences(): PreferenceContextValue {
  const value = use(PreferenceContext)
  if (value === null) {
    throw new Error('useFrontendPreferences requires FrontendProvider')
  }
  return value
}

import type {
  FrontendPreferences,
  InitialPreferenceOptions,
  PreferenceCookieResult,
  PreferencePolicy,
} from './types.js'
import { negotiateLocale } from './locale.js'
import { createPreferencePolicy } from './policy.js'
import { normalizePreferences, preferenceRecord, serializePreferences } from './preferences.js'

export const MAX_PREFERENCE_COOKIE_BYTES = 1024

function decodeCookie(value: string): PreferenceCookieResult {
  if (value.length > MAX_PREFERENCE_COOKIE_BYTES) {
    return { status: 'invalid', preferences: null }
  }
  try {
    const decoded: unknown = JSON.parse(decodeURIComponent(value))
    const record = preferenceRecord(decoded)
    if (record === null || typeof record.version !== 'number') {
      return { status: 'invalid', preferences: null }
    }
    if (record.version > 1) {
      return { status: 'future', preferences: null }
    }
    if (record.version !== 1) {
      return { status: 'invalid', preferences: null }
    }
    return { status: 'valid', preferences: normalizePreferences(record) }
  }
  catch {
    return { status: 'invalid', preferences: null }
  }
}
export function readPreferenceCookie(header: string, policy: PreferencePolicy): PreferenceCookieResult {
  const { name } = createPreferencePolicy(policy)
  const values = header.split(';').map(part => part.trim()).filter(part => part.startsWith(`${name}=`))
  if (values.length === 0) {
    return { status: 'missing', preferences: null }
  }
  if (values.length !== 1) {
    return { status: 'invalid', preferences: null }
  }
  return decodeCookie(values[0]?.slice(name.length + 1) ?? '')
}
export function preferenceCookie(preferences: FrontendPreferences, policy: PreferencePolicy): string {
  const validated = createPreferencePolicy(policy)
  const domain = validated.domain === undefined ? '' : `; Domain=${validated.domain}`
  const secure = validated.secure ? '; Secure' : ''
  const value = serializePreferences(preferences)
  return `${validated.name}=${value}; Path=/; SameSite=Lax; Max-Age=31536000${domain}${secure}`
}
export function resolveInitialPreferences(options: InitialPreferenceOptions): FrontendPreferences {
  const cookie = readPreferenceCookie(options.cookieHeader ?? '', options.policy)
  return cookie.preferences ?? normalizePreferences(null, negotiateLocale(options.acceptLanguage))
}
export function frontendRootAttributes(preferences: FrontendPreferences): {
  'lang': string
  'data-frontend-mode': string
  'data-frontend-palette': string
} {
  const normalized = normalizePreferences(preferences)
  return {
    'lang': normalized.locale,
    'data-frontend-mode': normalized.mode,
    'data-frontend-palette': normalized.palette,
  }
}

'use client'

import type { FooterLink, SiteFooterProps } from './shell-types.js'
import { safeHref } from './href.js'
import { cn } from './ui/cn.js'

const layout1Class = [
  'ztd-chrome mx-auto flex max-w-320 flex-wrap items-start justify-between gap-3 px-4 py-6 sm:flex-nowrap',
  'sm:items-center sm:gap-4 sm:px-6 lg:px-8',
].join(' ')

const EMPTY_LINKS: readonly FooterLink[] = []

export function SiteFooter({ copyright, links = EMPTY_LINKS }: SiteFooterProps): React.JSX.Element {
  return (
    <footer className={cn('ztd-footer border-t border-border bg-background text-help')}>
      <div className={cn(layout1Class)}>
        {copyright === undefined ? null : <span>{copyright}</span>}
        <div className={cn('ztd-footer-links flex flex-wrap items-center gap-3 sm:gap-4')}>
          {links.map(link => (
            <a
              key={`${link.href}:${link.label}`}
              href={safeHref(link.href, true)}
              className={cn('text-foreground underline-offset-3')}
              aria-label={link.ariaLabel}
            >
              {link.label}
            </a>
          ))}
        </div>
      </div>
    </footer>
  )
}

import { hasControlCharacters } from './text.js'

function validateHref(value: string): void {
  if (typeof value !== 'string' || value.length === 0 || value !== value.trim()
    || value.startsWith('//') || value.includes('\\') || hasControlCharacters(value)) {
    throw new TypeError('Link href must be a nonempty URL or relative path without control characters or backslashes')
  }
}

export function safeHref(value: string, allowMailto = false): string {
  validateHref(value)
  const url = new URL(value, 'https://frontend.invalid')
  if (url.protocol !== 'https:' && url.protocol !== 'http:' && !(allowMailto && url.protocol === 'mailto:')) {
    throw new TypeError('Link href supports HTTP, HTTPS, relative paths and optional mailto URLs')
  }
  return value
}

'use client'

import type { LinkProps } from './shell-types.js'

export function NativeLink(props: LinkProps): React.JSX.Element {
  return <a {...props} />
}

'use client'

import * as Select from '@radix-ui/react-select'
import { Check, ChevronDown } from 'lucide-react'
import { useFrontendPreferences } from './context.js'
import { shellMessages } from './messages.js'
import { isLocale } from './preferences.js'
import { focusClass, indicatorClass, menuClass, menuItemClass } from './ui/classes.js'
import { cn } from './ui/cn.js'
import { inertBackground } from './ui/inert.js'

const layout1Class = [
  'shrink-0 transition-transform duration-150 group-data-[state=open]:rotate-180',
  'motion-reduce:transition-none',
].join(' ')

const languages = [
  { id: 'en', label: 'English' },
  { id: 'zh-CN', label: '简体中文' },
] as const

export function LocaleSelect(): React.JSX.Element {
  const state = useFrontendPreferences()
  const messages = shellMessages(state.preferences.locale)
  return (
    <Select.Root
      value={state.preferences.locale}
      onValueChange={(locale) => {
        if (isLocale(locale)) {
          state.setLocale(locale)
        }
      }}
    >
      <Select.Trigger
        className={cn([
          'ztd-control ztd-locale group inline-flex min-h-11 min-w-11 items-center',
          'justify-center gap-1.5 rounded-lg border border-transparent bg-transparent',
          'px-2 py-2 text-control text-foreground hover:bg-muted',
          'data-[state=open]:bg-muted',
          focusClass,
        ].join(' '))}
        aria-label={messages.language}
      >
        <Select.Value />
        <Select.Icon><ChevronDown className={cn(layout1Class)} size={14} aria-hidden="true" /></Select.Icon>
      </Select.Trigger>
      <Select.Portal container={state.portalContainer}>
        <Select.Content asChild position="popper" sideOffset={8} align="end">
          <div
            className={cn(`${menuClass} ztd-locale-menu min-w-[max(128px,var(--radix-select-trigger-width))]`)}
            ref={inertBackground}
          >
            <Select.Viewport {...(state.styleNonce === undefined ? {} : { nonce: state.styleNonce })}>
              {languages.map(language => (
                <Select.Item key={language.id} value={language.id} className={cn(menuItemClass)}>
                  <Select.ItemIndicator className={cn(indicatorClass)}>
                    <Check size={16} aria-hidden="true" />
                  </Select.ItemIndicator>
                  <Select.ItemText><span lang={language.id}>{language.label}</span></Select.ItemText>
                </Select.Item>
              ))}
            </Select.Viewport>
          </div>
        </Select.Content>
      </Select.Portal>
    </Select.Root>
  )
}

import type { Locale } from './types.js'

function supportedLanguage(tag: string): Locale | null {
  const language = tag.trim().toLowerCase()
  if (language === 'en' || language.startsWith('en-')) {
    return 'en'
  }
  if (language === 'zh' || language === 'zh-cn' || language === 'zh-hans' || language.startsWith('zh-hans-')) {
    return 'zh-CN'
  }
  return null
}
function languageCandidate(part: string, order: number): { locale: Locale | null, quality: number, order: number } {
  const [tag = '', ...parameters] = part.split(';')
  const qualityText = parameters.find(parameter => parameter.trim().startsWith('q='))?.trim().slice(2)
  const quality = qualityText === undefined ? 1 : Number(qualityText)
  return { locale: supportedLanguage(tag), quality, order }
}
export function negotiateLocale(acceptLanguage = ''): Locale {
  const candidates = acceptLanguage.split(',').map(languageCandidate).filter(candidate => (
    candidate.locale !== null && Number.isFinite(candidate.quality) && candidate.quality > 0 && candidate.quality <= 1
  ))
  candidates.sort((a, b) => b.quality === a.quality ? a.order - b.order : b.quality - a.quality)
  return candidates[0]?.locale ?? 'en'
}

import type { PreferencePolicy, PreferencePolicyOptions } from './types.js'
import { isPreferenceRecord } from './preferences.js'
import { hasControlCharacters } from './text.js'

const optionKeys = new Set([
  'name',
  'domain',
  'secure',
  'mirrorKey',
])

function cookieDomain(value: unknown): string {
  if (typeof value !== 'string' || value.length > 253) {
    throw new TypeError('Cookie domain must be a DNS name of at most 253 characters')
  }
  const domain = value.toLowerCase()
  const labels = domain.split('.')
  const labelPattern = /^[a-z\d](?:[a-z\d-]{0,61}[a-z\d])?$/u
  if (labels.length < 2 || labels.some(label => !labelPattern.test(label)) || /^\d+$/u.test(labels.at(-1) ?? '')) {
    throw new TypeError('Cookie domain must be a DNS name without a scheme, port, leading dot or IP address')
  }
  return domain
}

function cookieName(value: unknown): string {
  const name = value === undefined ? 'frontend.preferences.v1' : value
  if (typeof name !== 'string' || name.length === 0 || name.length > 128 || !/^[\w!#$%&'*+.^|~-]+$/u.test(name)) {
    throw new TypeError('Cookie name must be a nonempty token of at most 128 characters')
  }
  return name
}

function cookieSecure(value: unknown): boolean {
  const secure = value === undefined ? true : value
  if (typeof secure !== 'boolean') {
    throw new TypeError('Cookie secure must be a boolean')
  }
  return secure
}

function validateScope(name: string, secure: boolean, domain: string | undefined): void {
  if (domain !== undefined && !secure) {
    throw new TypeError('Domain cookies require Secure')
  }
  if ((name.startsWith('__Secure-') || name.startsWith('__Host-')) && !secure) {
    throw new TypeError('Prefixed cookies require Secure')
  }
  if (name.startsWith('__Host-') && domain !== undefined) {
    throw new TypeError('__Host- cookies must be host-only')
  }
}

function notificationKey(mirrorKey: unknown): string | undefined {
  if (mirrorKey !== undefined && (typeof mirrorKey !== 'string' || mirrorKey.length === 0
    || mirrorKey.length > 128 || hasControlCharacters(mirrorKey))) {
    throw new TypeError('Mirror key must be nonempty, at most 128 characters and free of control characters')
  }
  return mirrorKey
}

function validateOptions(options: unknown): void {
  if (!isPreferenceRecord(options) || Object.keys(options).some(key => !optionKeys.has(key))) {
    throw new TypeError('Preference policy accepts only name, domain, secure and mirrorKey')
  }
}

export function createPreferencePolicy(options: PreferencePolicyOptions = {}): PreferencePolicy {
  validateOptions(options)
  const name = cookieName(options.name)
  const secure = cookieSecure(options.secure)
  const domain = options.domain === undefined ? undefined : cookieDomain(options.domain)
  validateScope(name, secure, domain)
  const mirrorKey = notificationKey(options.mirrorKey)
  return Object.freeze({
    name,
    secure,
    ...(domain === undefined ? {} : { domain }),
    ...(mirrorKey === undefined ? {} : { mirrorKey }),
  })
}

import type { FrontendPreferences, Locale, Mode, Palette } from './types.js'
import { LOCALES, MODES, PALETTES } from './types.js'

export const DEFAULT_PREFERENCES: Readonly<FrontendPreferences> = Object.freeze({
  version: 1,
  mode: 'system',
  palette: 'neutral',
  locale: 'en',
})

export function isMode(value: unknown): value is Mode {
  return new Set<unknown>(MODES).has(value)
}
export function isPalette(value: unknown): value is Palette {
  return new Set<unknown>(PALETTES).has(value)
}
export function isLocale(value: unknown): value is Locale {
  return new Set<unknown>(LOCALES).has(value)
}
export function isPreferenceRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object'
    && !Array.isArray(value) && Object.getPrototypeOf(value) === Object.prototype
}
export function preferenceRecord(value: unknown): Record<string, unknown> | null {
  return isPreferenceRecord(value) ? value : null
}
export function normalizePreferences(value: unknown, fallbackLocale: Locale = 'en'): FrontendPreferences {
  const record = preferenceRecord(value)
  if (record?.version !== 1) {
    return { ...DEFAULT_PREFERENCES, locale: fallbackLocale }
  }
  return {
    version: 1,
    mode: isMode(record.mode) ? record.mode : 'system',
    palette: isPalette(record.palette) ? record.palette : 'neutral',
    locale: isLocale(record.locale) ? record.locale : fallbackLocale,
  }
}
export function serializePreferences(value: FrontendPreferences): string {
  return encodeURIComponent(JSON.stringify(normalizePreferences(value)))
}

'use client'

import type { ReactNode } from 'react'
import type { FrontendPreferences, PreferencePolicy } from './types.js'
import { setNonce } from 'get-nonce'
import { useEffect, useMemo, useState, useSyncExternalStore } from 'react'
import { PreferenceContext } from './context.js'
import { frontendRootAttributes } from './cookies.js'
import { createPreferenceStore } from './store.js'

export type FrontendProviderProps = {
  initialPreferences: FrontendPreferences
  policy: PreferencePolicy
  children: ReactNode
  portalContainer?: HTMLElement | null
  styleNonce?: string
  onPreferencesChange?: (preferences: FrontendPreferences) => void
  onPersistenceError?: () => void
}
export function FrontendProvider(props: FrontendProviderProps): React.JSX.Element {
  const [store] = useState(() => createPreferenceStore(props.initialPreferences, props.policy))
  const snapshot = useSyncExternalStore(store.subscribe, store.getSnapshot, store.getServerSnapshot)
  const { onPreferencesChange, onPersistenceError, portalContainer, styleNonce } = props
  useEffect(() => {
    if (styleNonce !== undefined) {
      setNonce(styleNonce)
    }
  }, [styleNonce])
  useEffect(() => store.connect(), [store])
  useEffect(() => {
    const attributes = frontendRootAttributes(snapshot.preferences)
    for (const [key, value] of Object.entries(attributes)) {
      document.documentElement.setAttribute(key, value)
    }
    onPreferencesChange?.(snapshot.preferences)
  }, [snapshot.preferences, onPreferencesChange])
  useEffect(() => {
    if (snapshot.persistence === 'unavailable') {
      onPersistenceError?.()
    }
  }, [snapshot.persistence, onPersistenceError])
  const value = useMemo(() => ({
    ...snapshot,
    setMode: store.setMode,
    setPalette: store.setPalette,
    setLocale: store.setLocale,
    portalContainer: portalContainer ?? null,
    styleNonce,
  }), [
    snapshot,
    store,
    portalContainer,
    styleNonce,
  ])
  return <PreferenceContext value={value}>{props.children}</PreferenceContext>
}

import type { ComponentProps, ComponentType, ReactNode } from 'react'

export type Brand = {
  label: string
  homeHref: string
  mark?: ReactNode
}
export type LinkProps = Omit<ComponentProps<'a'>, 'href' | 'children'> & {
  href: string
  children: ReactNode
}
export type LinkComponent = ComponentType<LinkProps>
export type FooterLink = {
  label: string
  href: string
  ariaLabel?: string
}
export type SiteFooterProps = {
  copyright?: ReactNode
  links?: readonly FooterLink[]
}
export type ShellProps = {
  className?: string
  appbarClassName?: string
  chromeClassName?: string
  brandClassName?: string
  mainClassName?: string
  brand: Brand
  footer?: SiteFooterProps
  children: ReactNode
  projectActions?: ReactNode
  identity?: ReactNode
  mainId?: string
  linkComponent?: LinkComponent
}
export type ApplicationShellProps = {
  businessNavigation?: ReactNode
  contextSidebar?: ReactNode
  serviceNotice?: ReactNode
} & ShellProps

'use client'

import type { ApplicationShellProps, ShellProps } from './shell-types.js'
import { Appbar } from './appbar.js'
import { SiteFooter } from './footer.js'
import { cn } from './ui/cn.js'

export function PublicShell(props: ShellProps): React.JSX.Element {
  return (
    <div className={cn(`ztd-frontend flex min-h-dvh flex-col ${props.className ?? ''}`)}>
      <Appbar {...props} />
      <main
        className={cn(`min-w-0 flex-1 ${props.mainClassName ?? ''}`)}
        id={props.mainId ?? 'ztd-main'}
        tabIndex={-1}
      >
        {props.children}
      </main>
      {props.footer === undefined ? null : <SiteFooter {...props.footer} />}
    </div>
  )
}
export function ApplicationShell(props: ApplicationShellProps): React.JSX.Element {
  return (
    <div className={cn(`ztd-frontend ztd-application flex min-h-dvh flex-col ${props.className ?? ''}`)}>
      <Appbar {...props} appbarClassName={`sticky top-0 z-30 ${props.appbarClassName ?? ''}`} />
      {props.businessNavigation ?? null}
      {props.serviceNotice ?? null}
      <div className={cn('ztd-workspace flex flex-1')}>
        {props.contextSidebar ?? null}
        <main
          className={cn(`min-w-0 flex-1 ${props.mainClassName ?? ''}`)}
          id={props.mainId ?? 'ztd-main'}
          tabIndex={-1}
        >
          {props.children}
        </main>
      </div>
      {props.footer === undefined ? null : <SiteFooter {...props.footer} />}
    </div>
  )
}

import type { PreferenceSnapshot, PreferenceStore } from './store-types.js'
import type { FrontendPreferences, PreferencePolicy } from './types.js'
import { persistBrowserPreferences, readBrowserPreferences } from './browser-environment.js'
import { createPreferencePolicy } from './policy.js'
import { normalizePreferences, serializePreferences } from './preferences.js'

export function createPreferenceStore(initial: FrontendPreferences, policy: PreferencePolicy): PreferenceStore {
  const validatedPolicy = createPreferencePolicy(policy)
  const preferences = normalizePreferences(initial)
  const server: PreferenceSnapshot = {
    preferences,
    resolvedMode: preferences.mode === 'dark' ? 'dark' : 'light',
    persistence: 'unchanged',
  }
  let snapshot = server
  let systemDark = false
  const listeners = new Set<() => void>()
  function commit(next: FrontendPreferences, persistence = snapshot.persistence): void {
    const systemMode = systemDark ? 'dark' : 'light'
    const resolvedMode = next.mode === 'system' ? systemMode : next.mode
    snapshot = { preferences: next, resolvedMode, persistence }
    for (const listener of listeners) {
      listener()
    }
  }
  function change(next: FrontendPreferences): void {
    const normalized = normalizePreferences(next)
    const saved = persistBrowserPreferences(normalized, validatedPolicy)
    commit(normalized, saved ? 'saved' : 'unavailable')
  }
  function restore(): void {
    restoreFromCookie(snapshot, validatedPolicy, commit)
  }
  const actions = {
    setMode: (mode: FrontendPreferences['mode']) => change({ ...snapshot.preferences, mode }),
    setPalette: (palette: FrontendPreferences['palette']) => change({ ...snapshot.preferences, palette }),
    setLocale: (locale: FrontendPreferences['locale']) => change({ ...snapshot.preferences, locale }),
  }
  function connect(): () => void {
    return connectBrowser(validatedPolicy, {
      restore,
      setSystem: (dark) => {
        systemDark = dark
        commit(snapshot.preferences)
      },
    })
  }
  return {
    ...actions,
    getSnapshot: () => snapshot,
    getServerSnapshot: () => server,
    subscribe: (listener) => {
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
      }
    },
    connect,
  }
}
type BrowserActions = {
  restore: () => void
  setSystem: (dark: boolean) => void
}
function connectBrowser(
  policy: PreferencePolicy,
  actions: BrowserActions,
): () => void {
  const media = window.matchMedia('(prefers-color-scheme: dark)')
  const refreshMedia = (): void => {
    actions.setSystem(media.matches)
    actions.restore()
  }
  actions.setSystem(media.matches)
  actions.restore()
  const onStorage = (event: StorageEvent): void => {
    if (policy.mirrorKey !== undefined && event.key === policy.mirrorKey) {
      actions.restore()
    }
  }
  const onVisible = (): void => {
    if (document.visibilityState === 'visible') {
      actions.restore()
    }
  }
  window.addEventListener('focus', actions.restore)
  window.addEventListener('storage', onStorage)
  document.addEventListener('visibilitychange', onVisible)
  media.addEventListener('change', refreshMedia)
  return () => {
    window.removeEventListener('focus', actions.restore)
    window.removeEventListener('storage', onStorage)
    document.removeEventListener('visibilitychange', onVisible)
    media.removeEventListener('change', refreshMedia)
  }
}

function restoreFromCookie(
  snapshot: PreferenceSnapshot,
  policy: PreferencePolicy,
  commit: (preferences: FrontendPreferences, persistence: PreferenceSnapshot['persistence']) => void,
): void {
  const read = readBrowserPreferences(policy)
  if (read.status === 'unavailable') {
    commit(snapshot.preferences, 'unavailable')
    return
  }
  if (read.preferences === null) {
    return
  }
  const recovered = snapshot.persistence === 'unavailable'
  const changed = serializePreferences(read.preferences) !== serializePreferences(snapshot.preferences)
  if (changed || recovered) {
    commit(read.preferences, recovered ? 'saved' : snapshot.persistence)
  }
}

export function hasControlCharacters(value: string): boolean {
  return Array.from(value).some((character) => {
    const code = character.charCodeAt(0)
    return code < 32 || code === 127
  })
}

