.ztd-frontend :focus-visible,
.ztd-overlay :focus-visible {
  outline: 2px solid var(--ztd-focus);
  outline-offset: 2px;
}

.ztd-menu {
  --ztd-menu-x: 0px;
  --ztd-menu-y: 0px;

  box-shadow: 0 4px 16px color-mix(in srgb, var(--ztd-foreground) 10%, transparent);
  transform-origin: var(--radix-dropdown-menu-content-transform-origin,
    var(--radix-select-content-transform-origin, center));
}

.ztd-menu[data-side="bottom"] {
  --ztd-menu-y: -4px;
}

.ztd-menu[data-side="top"] {
  --ztd-menu-y: 4px;
}

.ztd-menu[data-side="left"] {
  --ztd-menu-x: 4px;
}

.ztd-menu[data-side="right"] {
  --ztd-menu-x: -4px;
}

.ztd-menu[data-state="open"] {
  animation: ztd-menu-enter 150ms ease-out;
}

.ztd-menu[data-state="closed"] {
  pointer-events: none;
  animation: ztd-menu-exit 100ms ease-in;
}

@keyframes ztd-menu-enter {
  from {
    opacity: 0;
    transform: translate(var(--ztd-menu-x), var(--ztd-menu-y)) scale(0.95);
  }

  to {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }
}

@keyframes ztd-menu-exit {
  from {
    opacity: 1;
    transform: translate(0, 0) scale(1);
  }

  to {
    opacity: 0;
    transform: translate(var(--ztd-menu-x), var(--ztd-menu-y)) scale(0.95);
  }
}

@media (pointer: coarse) {
  .ztd-menu-item {
    min-height: 44px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ztd-menu[data-state] {
    animation: none;
  }
}

