}

@keyframes ztd-slide-from-right {
  from {
    transform: translate3d(var(--initial-transform, 100%), 0, 0);
  }

  to {
    transform: translate3d(0, 0, 0);
  }
}

@keyframes ztd-slide-to-right {
  to {
    transform: translate3d(var(--initial-transform, 100%), 0, 0);
  }
}

